// ApplyDefaults se invoca tras Load para corregir valores cero o fuera de
// rango. Es idempotente: llamarla dos veces no altera el resultado.
package config

import (
	"runtime"
	"strings"
	"time"
)

// ApplyDefaults normaliza la Config rellenando ceros y recortando rangos
// peligrosos. Nunca devuelve error: es determinista y defensiva.
func ApplyDefaults(c *Config) {
	if c == nil {
		return
	}
	applyDiscordDefaults(&c.Discord)
	applyPostgresDefaults(&c.Postgres)
	applyRedisDefaults(&c.Redis)
	applyCerebrasDefaults(&c.Cerebras)
	applyAntiraidDefaults(&c.Antiraid)
	applyUIDefaults(&c.UI)
	applyLogDefaults(&c.Log)
	applyHealthDefaults(&c.Health)
}

// -------------------------------------------------------------
// Discord
// -------------------------------------------------------------

func applyDiscordDefaults(d *DiscordConfig) {
	if d.ShardCount < 0 {
		d.ShardCount = 0
	}
	if d.ShardID < 0 {
		d.ShardID = 0
	}
	if d.LargeThreshold < 50 {
		d.LargeThreshold = 250
	}
	if d.LargeThreshold > 1000 {
		d.LargeThreshold = 1000
	}
	if d.SyncTimeout <= 0 {
		d.SyncTimeout = 120 * time.Second
	}
	if d.CommandRegisterTTL <= 0 {
		d.CommandRegisterTTL = time.Hour
	}
	if d.Intents == 0 {
		d.Intents = defaultIntents()
	}
}

