// deja DISCORD_SHARD_COUNT=0. Escala con CPUs pero con techo de 16 por
// proceso para no saturar el rate limit del gateway.
func DefaultShardCount() int {
	procs := runtime.NumCPU()
	if procs < 1 {
		procs = 1
	}
	shards := procs / 2
	if shards < 1 {
		shards = 1
	}
	if shards > 16 {
		shards = 16
	}
	return shards
}

// -------------------------------------------------------------
// PostgreSQL
// -------------------------------------------------------------

func applyPostgresDefaults(p *PostgresConfig) {
	if p.MaxConns < 1 {
		p.MaxConns = 10
	}
	if p.MinConns < 0 {
		p.MinConns = 0
	}
	if p.MinConns > p.MaxConns {
		p.MinConns = p.MaxConns / 2
	}
	if p.MaxConnLifetime <= 0 {
		p.MaxConnLifetime = time.Hour
	}
	if p.MaxConnIdleTime <= 0 {
		p.MaxConnIdleTime = 30 * time.Minute
	}
	if p.ConnectTimeout <= 0 {
		p.ConnectTimeout = 10 * time.Second
	}
}

// -------------------------------------------------------------
// Redis
// -------------------------------------------------------------

func applyRedisDefaults(r *RedisConfig) {
	if strings.TrimSpace(r.Addr) == "" {
		r.Addr = "localhost:6379"
	}
	if r.PoolSize < 1 {
		r.PoolSize = 20
	}
	if r.MinIdleConns < 0 {
		r.MinIdleConns = 0
	}
	if r.MinIdleConns > r.PoolSize {
		r.MinIdleConns = r.PoolSize / 2
	}
	if r.DialTimeout <= 0 {
		r.DialTimeout = 5 * time.Second
	}
	if r.ReadTimeout <= 0 {
		r.ReadTimeout = 3 * time.Second
	}
	if r.WriteTimeout <= 0 {
		r.WriteTimeout = 3 * time.Second
	}
	if r.DefaultTTL <= 0 {
		r.DefaultTTL = 15 * time.Minute
	}
}

// -------------------------------------------------------------
// Cerebras
// -------------------------------------------------------------

func applyCerebrasDefaults(c *CerebrasConfig) {
	if strings.TrimSpace(c.BaseURL) == "" {
		c.BaseURL = "https://api.cerebras.ai/v1"
	}
	c.BaseURL = strings.TrimRight(c.BaseURL, "/")

	c.Model = strings.TrimSpace(c.Model)
	if c.Model == "" {
		c.Model = "gpt-oss-120b"
	} else if strings.EqualFold(c.Model, "llama-3.3-70b") {
		c.Model = "gpt-oss-120b"
	}
	if c.Timeout <= 0 {
		c.Timeout = 20 * time.Second
	}
	if c.MaxRetries < 0 {
		c.MaxRetries = 0
	}
	if c.MaxRetries > 10 {
		c.MaxRetries = 10
	}
	if c.RequestsPerMin < 1 {
		c.RequestsPerMin = 30
	}
	if c.BurstSize < 1 {
		c.BurstSize = 5
	}
	if c.BurstSize > c.RequestsPerMin {
		c.BurstSize = c.RequestsPerMin
	}
	if c.BatchSize < 1 {
		c.BatchSize = 8
	}
	if c.BatchSize > 64 {
		c.BatchSize = 64
	}
	if c.BatchFlushEvery <= 0 {
		c.BatchFlushEvery = 2 * time.Second
	}
}

// -------------------------------------------------------------
// Antiraid
// -------------------------------------------------------------

func applyAntiraidDefaults(a *AntiraidConfig) {
	if strings.TrimSpace(a.DefaultAction) == "" {
		a.DefaultAction = "timeout"
	}
	a.DefaultAction = strings.ToLower(a.DefaultAction)

	if a.WindowDuration <= 0 {
		a.WindowDuration = 10 * time.Second
	}
	if a.WindowDuration < time.Second {
		a.WindowDuration = time.Second
	}
	if a.ScoreThreshold < 0 {
		a.ScoreThreshold = 0
	}
	if a.ScoreThreshold > 100 {
		a.ScoreThreshold = 100
	}
	if a.JoinFloodLimit < 1 {
		a.JoinFloodLimit = 10
	}
	if a.MessageSpamLimit < 1 {
		a.MessageSpamLimit = 8
	}
	if a.MentionSpamLimit < 1 {
		a.MentionSpamLimit = 6
	}
	if a.LinkSpamLimit < 1 {
		a.LinkSpamLimit = 4
	}
	if a.MinAccountAge < 0 {
		a.MinAccountAge = 0
	}
	if a.LockdownCooldown <= 0 {
		a.LockdownCooldown = 5 * time.Minute
	}
}

// -------------------------------------------------------------
// UI
// -------------------------------------------------------------

func applyUIDefaults(u *UIConfig) {
	if u.ColorPrimary < 0 || u.ColorPrimary > 0xFFFFFF {
		u.ColorPrimary = 0x5865F2
	}
	if u.ColorSuccess < 0 || u.ColorSuccess > 0xFFFFFF {
		u.ColorSuccess = 0x57F287
	}
	if u.ColorWarning < 0 || u.ColorWarning > 0xFFFFFF {
		u.ColorWarning = 0xFEE75C
	}
	if u.ColorDanger < 0 || u.ColorDanger > 0xFFFFFF {
		u.ColorDanger = 0xED4245
	}
	if u.ColorNeutral < 0 || u.ColorNeutral > 0xFFFFFF {
		u.ColorNeutral = 0x99AAB5
	}
	if u.LiveFPS < 1 {
		u.LiveFPS = 4
	}
	if u.LiveFPS > 10 {
		u.LiveFPS = 10
	}
	if u.LiveMaxUpdates < 1 {
		u.LiveMaxUpdates = 60
	}
	if u.LiveMaxUpdates > 500 {
		u.LiveMaxUpdates = 500
	}
	if u.ProgressWidth < 5 {
		u.ProgressWidth = 18
	}
	if u.ProgressWidth > 60 {
		u.ProgressWidth = 60
	}
}

// -------------------------------------------------------------
// Log
// -------------------------------------------------------------

func applyLogDefaults(l *LogConfig) {
	l.Level = strings.ToLower(strings.TrimSpace(l.Level))
	switch l.Level {
	case "debug", "info", "warn", "error":
	default:
		l.Level = "info"
	}

	l.Format = strings.ToLower(strings.TrimSpace(l.Format))
	switch l.Format {
	case "json", "text":
	default:
		l.Format = "json"
	}
}

// -------------------------------------------------------------
// Health
// -------------------------------------------------------------

func applyHealthDefaults(h *HealthConfig) {
	if strings.TrimSpace(h.Addr) == "" {
		h.Addr = ":8080"
	}
	if h.ReadTimeout <= 0 {
		h.ReadTimeout = 5 * time.Second
	}
	if h.WriteTimeout <= 0 {
		h.WriteTimeout = 10 * time.Second
	}
}
